using Microsoft.Windows.AppNotifications;using SobhanNotificationHub.Models;using SobhanNotificationHub.Services;using SobhanNotificationHub.Tray;
namespace SobhanNotificationHub.Notifications;public sealed class WindowsNotificationService:IDisposable{private readonly NotificationActionRouter _router;private readonly TrayIconService _tray;private bool _registered;public WindowsNotificationService(NotificationActionRouter router,TrayIconService tray){_router=router;_tray=tray;}public Task InitializeAsync(){try{var manager=AppNotificationManager.Default;manager.NotificationInvoked+=OnInvoked;manager.Register();_registered=true;LoggingService.Info("app_notification_registered");}catch(Exception ex){LoggingService.Error("app_notification_register",ex);}return Task.CompletedTask;}public Task ShowAsync(SobhanNotification item,ClientConfig config,CancellationToken ct){try{if(!_registered)throw new InvalidOperationException("App notifications unavailable");var notification=NotificationRenderer.Build(item,config).BuildNotification();AppNotificationManager.Default.Show(notification);LoggingService.Info("notification_shown",$"id={item.Id};module={item.Module}");}catch(Exception ex){LoggingService.Error("notification_fallback",ex);_tray.ShowFallback(item.Title,item.SafeBody,item.ActionUrl);}return Task.CompletedTask;}private async void OnInvoked(AppNotificationManager sender,AppNotificationActivatedEventArgs args){try{var values=Parse(args.Argument);var id=long.TryParse(values.GetValueOrDefault("notificationId"),out var parsed)?parsed:0;var action=values.GetValueOrDefault("action")??"open";var reply=args.UserInput.TryGetValue("replyText",out var input)?input?.ToString():null;await _router.RouteAsync(id,action,reply,CancellationToken.None);}catch(Exception ex){LoggingService.Error("notification_activation",ex);}}private static Dictionary<string,string> Parse(string value)=>value.Split('&',StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Split('=',2)).ToDictionary(x=>Uri.UnescapeDataString(x[0]),x=>x.Length>1?Uri.UnescapeDataString(x[1]):"");public void Dispose(){if(!_registered)return;try{AppNotificationManager.Default.NotificationInvoked-=OnInvoked;AppNotificationManager.Default.Unregister();}catch{} _registered=false;}}
